    unitsReversed: number;
    /** `unitsOrdered` minus `unitsReversed`. */
    netUnits: number;
    /** Goods net of VAT on invoices issued in the period, before shipping, discounts and reversals. */
    grossSales: number;
    /** Always 0 until a discount exists. */
    discounts: number;
